typedef unsigned long long big_int;
extern "C" unsigned int strlen(const char *);
extern "C" void *memcpy(void *, const void *, unsigned int);
extern "C" void *memset(void *, int, unsigned int);

class stringx;

class string_buf
{
protected:
  friend class stringx;
  big_int *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;

  inline int blocks_needed(int chars)
  {
    chars++;
    if (chars % sizeof(big_int) != 0)
      return (chars / sizeof(big_int) + 1);
    else
      return (chars / sizeof(big_int));
  }

public:
  inline int get_ref() { return ref_count; }

  inline void set_char_length(int len)
  {
    char_length = len;
    block_length = blocks_needed(len);
    memset((char *)data + len, 0, max_blocks * sizeof(big_int) - len);
  }

  void null_terminate() const;
};

class stringx
{
protected:
  char *chars;
  string_buf *my_buf;

  static void add_buf_to_cache(string_buf *buf);
  bool aggressively_cache_buffer();

public:
  void append(const char *str, int len = -1);

  inline void lock()
  {
    if (my_buf->get_ref() > 1)
      fork_data();
  }

  void fork_data(int new_len = -1);
  void make_room(int size);
};

void stringx::append(const char *str, int len)
{
  if (str == 0) {
    append("");
    return;
  }
  if (len == -1) len = strlen(str);
  lock();
  make_room(my_buf->char_length + len);
  memcpy(chars + my_buf->char_length, str, len);
  bool cache_it = false;
  if (my_buf->char_length == 0)
    cache_it = true;
  my_buf->set_char_length(my_buf->char_length + len);
  my_buf->null_terminate();
  if (!aggressively_cache_buffer())
    if (cache_it)
      add_buf_to_cache(my_buf);
}
